1	// Regression coverage for revoking an organization's existing access by
2	// publishing the complete policy set as empty. An empty published set is a
3	// genuine version, not the absence of one: before the revocation the probe
4	// request is allowed by the matching allow policy at the allow version;
5	// after it the same request is default-denied at the new empty version —
6	// never at version 0 (nothing published) and never with the old policy's
7	// matched identifiers left over.
8	//
9	// The revocation publish and the read decisions share one organization
10	// audit chain, and the chain is the arbiter when they overlap: a decision
11	// record positioned before the revocation record must rest on the allow
12	// version, one positioned after it must rest on the empty version. A later
13	// decision may never keep using the old allow version, and an earlier
14	// decision may never carry a version that had not been published yet. Each
15	// request's returned result and its recorded decision must agree exactly on
16	// allowed, reason, matched list and actual version, and one successful
17	// revocation produces exactly one new version and one policy-change record.
18	//
19	// Everything here is judged through the public business surface — Publish,
20	// Decide, CurrentVersion, Policies, the audit query/export entries and the
21	// recheck entries — with no change to the authorization rules.
22	package darksafe
23	
24	import (
25		"errors"
26		"reflect"
27		"sync"
28		"testing"
29	)
30	
31	// revokeEmptyShapes are the ways "no policies" reaches Publish; every shape
32	// is authorization-equivalent and must revoke identically.
33	func revokeEmptyShapes() map[string][]Policy {
34		return map[string][]Policy{
35			"nil slice":      nil,
36			"empty slice":    {},
37			"empty make":     make([]Policy, 0),
38			"empty with cap": make([]Policy, 0, 4),
39		}
40	}
41	
42	// revokeAllowSet is the single allow policy the empty publish revokes.
43	func revokeAllowSet() []Policy {
44		return []Policy{allowPolicy("p-ledger-read", "u1", "read", "org/acme/ledger", false)}
45	}
46	
47	// revokeReadRequest is the fully populated, organization-consistent read
48	// used throughout: one enabled subject, one resource, all three
49	// organizations equal, valid identifiers, action and scope.
50	func revokeReadRequest(org string) OrgRequest {
51		return request(org, "u1", "ledger-1", "org/acme/ledger", "read")
52	}
53	
54	// revokeAllowDecision is the only acceptable pre-revocation outcome: allowed
55	// by the matching allow policy at version 1.
56	func revokeAllowDecision() Decision {
57		return Decision{
58			Allowed: true, Reason: "matched allow policy",
59			Matched: []string{"p-ledger-read"}, Version: 1,
60		}
61	}
62	
63	// revokeDenyDecision is the only acceptable post-revocation outcome:
64	// default-denied at the new empty version 2 — not version 0, not the old
65	// allow version, and with no matched identifiers carried over.
66	func revokeDenyDecision() Decision {
67		return Decision{
68			Allowed: false, Reason: "no matching allow policy",
69			Matched: []string{}, Version: 2,
70		}
71	}
72	
73	// checkRevokeDecisionRecord pins one decision record to the exact request
74	// and decision the scenario allows at its chain position.
75	func checkRevokeDecisionRecord(t *testing.T, rec AuditRecord, req OrgRequest, want Decision) {
76		t.Helper()
77		if rec.Kind != AuditDecision || rec.Decision == nil {
78			t.Fatalf("record %d is not a decision record: %+v", rec.Seq, rec)
79		}
80		if !reflect.DeepEqual(rec.Decision.Request, req) {
81			t.Fatalf("record %d request = %+v, want %+v", rec.Seq, rec.Decision.Request, req)
82		}
83		if !reflect.DeepEqual(rec.Decision.Decision, want) {
84			t.Fatalf("record %d decision = %+v, want %+v", rec.Seq, rec.Decision.Decision, want)
85		}
86		if rec.Decision.Decision.Version == 0 {
87			t.Fatalf("record %d fell back to version 0 (no published version)", rec.Seq)
88		}
89	}
90	
91	// setupRevokeStore publishes the allow set as version 1 and returns the
92	// store, the probe request and the decision the probe must see until the
93	// revocation lands.
94	func setupRevokeStore(t *testing.T, org string) (*Store, OrgRequest, Decision) {
95		t.Helper()
96		s := NewStore()
97		if v, err := s.Publish(org, 0, revokeAllowSet()); err != nil || v != 1 {
98			t.Fatalf("publish allow v1 = %d, %v; want 1, nil", v, err)
99		}
100		req := revokeReadRequest(org)
101		wantAllow := revokeAllowDecision()
102		if d := evaluate(req, revokeAllowSet(), 1); !reflect.DeepEqual(d, wantAllow) {
103			t.Fatalf("fixture: allow set must allow the probe at v1, got %+v", d)
104		}
105		return s, req, wantAllow
106	}
107	
108	// TestPublishEmptySetRevokesAccess pins the non-overlapping contract: a read
109	// completed before the revocation starts keeps its allow conclusion, a read
110	// submitted only after the revocation publish returned is always denied at
111	// the empty version, and the shared audit chain records exactly one new
112	// version, one policy-change record and one complete decision record per
113	// request.
114	func TestPublishEmptySetRevokesAccess(t *testing.T) {
115		for shape, emptyPolicies := range revokeEmptyShapes() {
116			t.Run(shape, func(t *testing.T) {
117				org := "acme-revoke-" + shape
118				s, req, wantAllow := setupRevokeStore(t, org)
119				allow := revokeAllowSet()
120	
121				// Boundary 1: the read completes before the revocation starts.
122				before := s.Decide(org, req)
123				if !reflect.DeepEqual(before, wantAllow) {
124					t.Fatalf("pre-revocation decision = %+v, want %+v", before, wantAllow)
125				}
126	
127				// The revocation: publish the complete policy set as empty. It
128				// succeeds as exactly the next consecutive version.
129				newVersion, err := s.Publish(org, 1, emptyPolicies)
130				if err != nil || newVersion != 2 {
131					t.Fatalf("publish empty revocation = %d, %v; want 2, nil", newVersion, err)
132				}
133				if got := s.CurrentVersion(org); got != 2 {
134					t.Fatalf("current version = %d, want 2 after revocation", got)
135				}
136				// Exactly one new version was consumed: 3 does not exist.
137				if _, err := s.Policies(org, 3); !errors.Is(err, ErrVersionNotFound) {
138					t.Fatalf("version 3 exists after one revocation, err = %v", err)
139				}
140				// The new version is a genuine empty set; the allow version is
141				// untouched history underneath it.
142				gotV2, err := s.Policies(org, 2)
143				if err != nil || len(gotV2) != 0 {
144					t.Fatalf("Policies(v2) = %+v, %v; want empty, nil", gotV2, err)
145				}
146				gotV1, err := s.Policies(org, 1)
147				if err != nil || !reflect.DeepEqual(gotV1, allow) {
148					t.Fatalf("Policies(v1) = %+v, %v; want the original allow set", gotV1, err)
149				}
150	
151				// Boundary 2: a read submitted only after the revocation publish
152				// returned is denied at the empty version.
153				wantDeny := revokeDenyDecision()
154				after := s.Decide(org, req)
155				if !reflect.DeepEqual(after, wantDeny) {
156					t.Fatalf("post-revocation decision = %+v, want %+v", after, wantDeny)
157				}
158				if after.Version == 0 {
159					t.Fatalf("denial fell back to version 0 as if nothing were published")
160				}
161	
162				// The shared audit chain: publish v1, the allowed read, the
163				// revocation publish, the denied read — four records, gapless,
164				// nothing omitted and nothing extra.
165				recs := drainAudit(t, s, org, "", "")
166				if len(recs) != 4 {
167					t.Fatalf("audit records = %d, want 4", len(recs))
168				}
169				for i, r := range recs {
170					if r.Seq != i+1 || r.Org != org {
171						t.Fatalf("record %d has unexpected seq/org: %+v", i+1, r)
172					}
173				}
174				if recs[0].Kind != AuditPolicyChange || recs[0].Change == nil ||
175					recs[0].Change.Version != 1 ||
176					!reflect.DeepEqual(recs[0].Change.Policies, allow) ||
177					recs[0].Change.RolledBack {
178					t.Fatalf("v1 change record altered: %+v", recs[0])
179				}
180				// The pre-revocation read keeps its allow conclusion on the chain.
181				checkRevokeDecisionRecord(t, recs[1], req, wantAllow)
182				// The revocation left exactly one policy-change record: the new
183				// version 2 with empty content, an ordinary publish (no rollback).
184				chg := recs[2].Change
185				if recs[2].Kind != AuditPolicyChange || chg == nil {
186					t.Fatalf("record 3 is not the revocation change: %+v", recs[2])
187				}
188				if chg.Version != 2 || len(chg.Policies) != 0 ||
189					chg.RolledBack || chg.SourceVersion != 0 {
190					t.Fatalf("revocation record = %+v, want version 2, empty policies, plain publish", chg)
191				}
192				// The post-revocation read is recorded denied at the empty version.
193				checkRevokeDecisionRecord(t, recs[3], req, wantDeny)
194	
195				// The chain verifies, and each recorded decision rechecks to
196				// exactly itself from the organization's own history.
197				exported, cp, err := s.AuditExport(org, 0)
198				if err != nil {
199					t.Fatalf("AuditExport: %v", err)
200				}
201				if err := VerifyAudit(org, exported, cp); err != nil {
202					t.Fatalf("chain does not verify after revocation: %v", err)
203				}
204				rcAllow, err := s.RecheckDecision(org, 2)
205				if err != nil || !reflect.DeepEqual(rcAllow, wantAllow) {
206					t.Fatalf("recheck of pre-revocation read = %+v, %v; want %+v", rcAllow, err, wantAllow)
207				}
208				rcDeny, err := s.RecheckDecision(org, 4)
209				if err != nil || !reflect.DeepEqual(rcDeny, wantDeny) {
210					t.Fatalf("recheck of post-revocation read = %+v, %v; want %+v", rcDeny, err, wantDeny)
211				}
212	
213				// Offline replay from the export must find the empty v2 content
214				// in the revocation record before the denial and must not fall
215				// back to version 0 or substitute the allowing v1.
216				review, err := RecheckDecisionOffline(org, exported, cp, 4)
217				if err != nil {
218					t.Fatalf("RecheckDecisionOffline after revocation: %v", err)
219				}
220				if !review.Consistent || !reflect.DeepEqual(review.Recomputed, wantDeny) {
221					t.Fatalf("offline review of denial = %+v, want consistent %+v", review, wantDeny)
222				}
223			})
224		}
225	}
226	
227	// TestConcurrentPublishEmptySetRevocation overlaps read decisions with the
228	// revocation publish as a genuine race. Neither side is required to finish
229	// first and a run need not observe both outcomes; the organization audit
230	// chain decides what every decision must look like. Decision records before
231	// the revocation record must be allows at version 1, records after it must
232	// be denials at the empty version 2, and the decisions returned to the
233	// callers must be exactly the decisions on the chain.
234	func TestConcurrentPublishEmptySetRevocation(t *testing.T) {
235		const (
236			iterations    = 50
237			readers       = 8
238			readsPerReply = 10
239		)
240		for iter := 0; iter < iterations; iter++ {
241			org := "acme-revoke-race"
242			s, req, wantAllow := setupRevokeStore(t, org)
243			wantDeny := revokeDenyDecision()
244	
245			// A read that completes before the revocation starts keeps its allow
246			// conclusion; it joins the returned-decision accounting below.
247			var returned []Decision
248			var mu sync.Mutex
249			collect := func(d Decision) {
250				mu.Lock()
251				returned = append(returned, d)
252				mu.Unlock()
253			}
254			collect(s.Decide(org, req))
255	
256			start := make(chan struct{})
257			publishResult := make(chan error, 1)
258			var wg sync.WaitGroup
259			wg.Add(1)
260			go func() {
261				defer wg.Done()
262				<-start
263				v, err := s.Publish(org, 1, nil)
264				if err == nil && v != 2 {
265					t.Errorf("revocation publish returned version %d, want 2", v)
266				}
267				publishResult <- err
268			}()
269			for r := 0; r < readers; r++ {
270				wg.Add(1)
271				go func() {
272					defer wg.Done()
273					<-start
274					for i := 0; i < readsPerReply; i++ {
275						collect(s.Decide(org, req))
276					}
277				}()
278			}
279			close(start)
280			wg.Wait()
281			if err := <-publishResult; err != nil {
282				t.Fatalf("iter %d: revocation publish failed: %v", iter, err)
283			}
284	
285			// A read submitted only after the revocation returned is denied.
286			collect(s.Decide(org, req))
287	
288			// Every returned decision is exactly one of the two legal outcomes —
289			// never version 0, never a stale allow version with the old matched
290			// list after the revocation, never a partial shape.
291			allowReturns, denyReturns := 0, 0
292			for _, d := range returned {
293				switch {
294				case reflect.DeepEqual(d, wantAllow):
295					allowReturns++
296				case reflect.DeepEqual(d, wantDeny):
297					denyReturns++
298				default:
299					t.Fatalf("iter %d: unexpected returned decision %+v", iter, d)
300				}
301			}
302	
303			// Exactly one new version and one policy-change record came out of
304			// the revocation; every access request left exactly one decision
305			// record — none missing, none extra.
306			if got := s.CurrentVersion(org); got != 2 {
307				t.Fatalf("iter %d: current version = %d, want 2", iter, got)
308			}
309			if _, err := s.Policies(org, 3); !errors.Is(err, ErrVersionNotFound) {
310				t.Fatalf("iter %d: version 3 exists, err = %v", iter, err)
311			}
312			totalDecisions := 1 + readers*readsPerReply + 1
313			recs := drainAudit(t, s, org, "", "")
314			if len(recs) != 2+totalDecisions {
315				t.Fatalf("iter %d: audit records = %d, want %d (2 changes + %d decisions)",
316					iter, len(recs), 2+totalDecisions, totalDecisions)
317			}
318			for i, r := range recs {
319				if r.Seq != i+1 {
320					t.Fatalf("iter %d: record %d has sequence %d; the chain must be gapless", iter, i+1, r.Seq)
321				}
322			}
323			if recs[0].Kind != AuditPolicyChange || recs[0].Change == nil || recs[0].Change.Version != 1 {
324				t.Fatalf("iter %d: first record is not the v1 publish: %+v", iter, recs[0])
325			}
326			revokeSeq := 0
327			for _, r := range recs[1:] {
328				if r.Kind != AuditPolicyChange {
329					continue
330				}
331				if revokeSeq != 0 {
332					t.Fatalf("iter %d: second revocation record at seq %d (first at %d)", iter, r.Seq, revokeSeq)
333				}
334				revokeSeq = r.Seq
335				chg := r.Change
336				if chg == nil || chg.Version != 2 || len(chg.Policies) != 0 ||
337					chg.RolledBack || chg.SourceVersion != 0 {
338					t.Fatalf("iter %d: revocation record = %+v, want version 2, empty policies, plain publish", iter, chg)
339				}
340			}
341			if revokeSeq == 0 {
342				t.Fatalf("iter %d: revocation left no policy-change record", iter)
343			}
344	
345			// Chain position decides: before the revocation record every decision
346			// is the allow at v1; after it every decision is the denial at the
347			// empty v2. No later record may keep the old allow version and no
348			// earlier record may carry the not-yet-published v2.
349			allowRecords, denyRecords := 0, 0
350			for _, r := range recs {
351				if r.Kind != AuditDecision {
352					continue
353				}
354				if r.Seq < revokeSeq {
355					checkRevokeDecisionRecord(t, r, req, wantAllow)
356					allowRecords++
357				} else {
358					checkRevokeDecisionRecord(t, r, req, wantDeny)
359					denyRecords++
360				}
361			}
362			// The returned results and the recorded decisions are the same
363			// outcomes: identical requests, so the per-shape counts must match.
364			if allowRecords != allowReturns || denyRecords != denyReturns {
365				t.Fatalf("iter %d: returned vs recorded decisions disagree: allows %d/%d, denials %d/%d",
366					iter, allowReturns, allowRecords, denyReturns, denyRecords)
367			}
368	
369			// The full chain verifies and every recorded decision rechecks to
370			// exactly itself against the version it declared.
371			exported, cp, err := s.AuditExport(org, 0)
372			if err != nil {
373				t.Fatalf("iter %d: AuditExport: %v", iter, err)
374			}
375			if err := VerifyAudit(org, exported, cp); err != nil {
376				t.Fatalf("iter %d: chain does not verify: %v", iter, err)
377			}
378			for _, r := range recs {
379				if r.Kind != AuditDecision {
380					continue
381				}
382				got, err := s.RecheckDecision(org, r.Seq)
383				if err != nil || !reflect.DeepEqual(got, r.Decision.Decision) {
384					t.Fatalf("iter %d: recheck of seq %d = %+v, %v; want %+v",
385						iter, r.Seq, got, err, r.Decision.Decision)
386				}
387			}
388		}
389	}
