		{ID: "p-ledger-read-2026", Subject: target, Action: "read", Scope: scope, Effect: darksafe.EffectAllow},
		{ID: "p-ledger-write-deny", Subject: target, Action: "write", Scope: scope, Effect: darksafe.EffectDeny},
